create table FM_CHANNEL (COUNTER_FLAG VARCHAR(1) null  ,CHANNEL_TYPE VARCHAR(10) null  ,CHANNEL_SHORT VARCHAR(200) null  ,CHANNEL VARCHAR(10) not null  ,TRAN_TIMESTAMP VARCHAR(26) not null  ,COMPANY VARCHAR(20) null  ,CHANNEL_CLASS VARCHAR(3) null  ,CHANNEL_DESC VARCHAR(500) not null  , primary key(CHANNEL));